worked_example.braincode:
ENTRYPOINT $v1
TASK $v2 ANCHOR @d2026-09-30 {
  ACTION op_check_replied(attr_target=role_manager, attr_deadline=@d2026-10-02) -> $v3:BOOL
  IF NOT $v3 THEN { ACTION op_send_email(attr_recipient=role_manager, attr_content=int_follow_up(attr_tone=val_polite)) }
}

ENTRYPOINT $v1
CONVO $v2 {
  TURN $v3 SPEAKER=USER { UTTER int_request_extension(attr_recipient=role_manager, attr_duration=2, attr_unit=val_day) }
  TURN $v4 SPEAKER=USER REVISES $v3 { UTTER int_request_extension(attr_recipient=role_manager, attr_duration=3, attr_unit=val_day) }
}

TASK $follow_up {
  ACTION act_check_replied(target=role_manager, deadline=@d2025-06-06) -> $replied : BOOL
  IF NOT $replied THEN {
    ACTION act_send_email(recipient=role_manager, content=intent_follow_up(tone=value_polite))
  }
}

LET $itinerary : LIST[PROPOSITION] = [intent_location(place=entity_paris), intent_location(place=entity_lyon)]
FOR EACH $stop IN $itinerary {
  ACTION act_search_travel(destination=$stop)
}

